import { aggregateValue } from "../../../data/aggregations";
import type { DataRow } from "../../../data/normalizeData";
import type { SankeyChartComponent } from "../../../schema/hyperpbiSchema";
import type { ChartAdapter, ChartDatumBinding } from "./types";
import { baseOption, semanticResult, sourceIndices } from "./shared";

export const sankeyAdapter: ChartAdapter<SankeyChartComponent>={type:"sankeyChart",fields:component=>[component.sourceField,component.targetField,component.valueField].filter((field):field is string=>Boolean(field)),build(component,rows,context){const links=new Map<string,{source:string;target:string;rows:DataRow[]}>();const nodeRows=new Map<string,DataRow[]>();for(const row of rows){const source=String(row[component.sourceField]??"(Blank)"),target=String(row[component.targetField]??"(Blank)");const key=`${source}\u0000${target}`;const link=links.get(key)??{source,target,rows:[]};link.rows.push(row);links.set(key,link);for(const node of [source,target]){const entries=nodeRows.get(node)??[];entries.push(row);nodeRows.set(node,entries);}}
    const nodes=Array.from(nodeRows.keys()).map(name=>({name}));const edgeData=Array.from(links.values()).map(link=>({source:link.source,target:link.target,value:component.valueField?Number(aggregateValue(link.rows,component.valueField,component.aggregation??"sum")??0):link.rows.length}));const bindings:ChartDatumBinding[]=[];Array.from(nodeRows.entries()).forEach(([name,nodeData],dataIndex)=>bindings.push({seriesIndex:0,dataIndex,dataType:"node",sourceRowIndices:sourceIndices(nodeData,context),value:name}));Array.from(links.values()).forEach((link,dataIndex)=>bindings.push({seriesIndex:0,dataIndex,dataType:"edge",sourceRowIndices:sourceIndices(link.rows,context),field:component.sourceField,value:[link.source,link.target]}));return semanticResult({...baseOption(context),series:[{type:"sankey",orient:component.orientation??"horizontal",nodeAlign:component.nodeAlign??"justify",selectedMode:"multiple",data:nodes,links:edgeData,emphasis:{focus:"adjacency"}}]},component,bindings);}};
