import { AiPromptSettings } from "./aiPromptSettings";
export interface PromptQualityCheck { label: string; passed: boolean; }
export function promptQualityChecks(prompt: string, settings: AiPromptSettings): PromptQualityCheck[] { return [
    {label:"Field aliases included",passed:/AVAILABLE FIELD ALIASES/i.test(prompt)}, {label:"Dashboard goal included",passed:prompt.includes(settings.goal)}, {label:"Relevant components included",passed:/COMPONENTS AVAILABLE/i.test(prompt)}, {label:"JSON-only output required",passed:/one JSON object only/i.test(prompt)}, {label:"JavaScript forbidden",passed:/no JavaScript/i.test(prompt)}, {label:"Version 2.0 contract included",passed:/schema version 2\.0/i.test(prompt)}, {label:"Dataset language included only when needed",passed:settings.calculationsRequired?/Allowed operations/i.test(prompt):true}, {label:"Map/provider rules included",passed:!settings.mapRequired || /MAP RULES:/i.test(prompt)}, {label:"Interaction rules included",passed:/INTERACTIONS:/i.test(prompt)}, {label:"Security rules included",passed:/Security:/i.test(prompt)}, {label:"Current specification scoped to improvement",passed:settings.job==="improve"?/CURRENT DASHBOARD/i.test(prompt):!/CURRENT DASHBOARD/i.test(prompt)} ]; }
