export interface StudioLayoutPreference { editorPercent: number; bottomHeight: number; bottomOpen: boolean; advanced: boolean; }
export const defaultStudioLayout: StudioLayoutPreference = { editorPercent: 38, bottomHeight: 210, bottomOpen: true, advanced: false };
export function parseStudioLayout(value?: string): StudioLayoutPreference { try { const parsed = JSON.parse(value ?? "") as Partial<StudioLayoutPreference>; return { editorPercent: Math.min(75, Math.max(25, Number(parsed.editorPercent) || defaultStudioLayout.editorPercent)), bottomHeight: Math.min(520, Math.max(120, Number(parsed.bottomHeight) || defaultStudioLayout.bottomHeight)), bottomOpen: parsed.bottomOpen ?? defaultStudioLayout.bottomOpen, advanced: parsed.advanced ?? defaultStudioLayout.advanced }; } catch { return defaultStudioLayout; } }
